def count_distinct_strings(n, s):
    if n == 1:
        return 1

    mod = 10**9 + 7
    dp = [1] * n
    memo = defaultdict(bool)

    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i] -= dp[j]
                if dp[i] < 0:
                    dp[i] += mod
        if memo[(s[i], s[j])] == False:
            memo[(s[i], s[j])] = True
            dp[i] = (dp[i] + 1) % mod

