@lru_cache(maxsize=None)
def count_ways(height):
    if height == 0:
        return 0
    elif height == 1:
        return 1

    max_expr = ((2814749766880 // height) % (10**9 + 7) * pow(755, 2, (10**9 + 7))) % (10**9 + 7)
    if height > max_expr:
        max_expr = height

    count = max_sum = 0
    for expansion in range(1, max_expr + 1):
        remaining = max_expr - expansion
        count += max_sum * count_ways(remaining) % (10**9 + 7)
        max_sum += count_ways(expansion) % (10**9 + 7)

