from typing import List

def min_operations(arr: List[int]) -> int:
    operations = 0
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            if arr[i-1] <= 1 or arr[i] == 1 and arr[i-1] == 2:
                operations += 1
            else:
                x = arr[i]
                y = arr[i-1]
                if y <= 1 or math.sqrt(y) == x:
                    operations += 1
                else:
                    max_diff = max(abs(min(3, math.sqrt(x)) - 1), abs(max(x - math.sqrt(y), math.sqrt(x) + 1) - y))
                    if y >= x + max_diff:
                        arr[i] = 1
                    else:
                        x -= max_diff
                        y -= max_diff
                        arr[i] = y if x <= y else x
                    operations += 1
    return operations

