    cols = len(grid[0])
    q, r, c, deltaR, deltaC = query[index]
    if r < 0 or c < 0 or r >= rows or c >= cols:
        return 0
    if deltaR < 0 or deltaC < 0 or deltaR >= rows or deltaC >= rows:
        return 0

    count = 0
    for i in range(r, min(r+deltaR, rows)):
        for j in range(c, min(c+deltaC, cols)):
            try:
                if grid[i][j] == grid[r][c]:
                    count += 1
            except IndexError:
                # If index is out of bounds, we're expecting a substraction of one dimension.
