from math import comb

def generate_partitions(n, mod=1000000007):
    if n == 0:
        return 1
    partitions = [0] * (n + 1)
    partitions[0] = 1
    for i in range(1, n + 1):
        partitions[i] = partitions[i - 1]
        for j in range(1, i + 1):
            partitions[i] = (partitions[i] + partitions[i - j]) % mod
    return partitions[n]

def calculate_step_ways(n, mod=1000000007):
    if n == 1:
        return 1
    partitions = [0] * (n + 1)
    partitions[0] = 1
    for i in range(1, n + 1):
        partitions[i] = partitions[i - 1] * generate_partitions(i, mod) % mod
    return partitions[n] * pow(comb(n, 1), mod - 2, mod) % mod

def euler():
    n = 7
    steps = [0, 1, 0, 0, 0, 0, 0]
    if steps[2] != 0:
        steps[2] = pow(2, steps[2], 1000000007)
    for i in range(3, n + 1):
        steps[i] = 2 * steps[i - 1] % 1000000007
        steps[i] = steps[i] * pow(steps[i - 1], n - i - 1, 1000000007) % 1000000007
    return generate_partitions(steps[-1], steps[1])

