from collections import defaultdict

def max_meet_at(input_colors):
    colors = sorted(input_colors)
    groups = defaultdict(list)

    for color in colors:
        if not groups[color]:
            groups[(0, color)].append(0)
            groups[(1, color)].append(1)
        else:
            index = groups[color][-1]
            groups[color].remove(index)
            groups[(0, color)].append(index)
            groups[(1, color)].append(index + 1)

    dp = [(-1, -1)] * 51
    dp[0] = (0, 0)

    for i in range(len(groups)):
        for state, index in dp[:]:
            for k in range(20, -1, -1):
                if state & (1 << k):
                    if not groups[(1+k-1, k + color)].and_contains(index):
                        continue

                    if i + (0 - k <= len(groups) - 1) + (1 + k <= len(groups) - 1) < len(dp):
                        dp[i + (0 - k <= len(groups) - 1)] = (state | (1 << k), groups[(1 + k, 1 + k + color)].remove(index))

    return max(dp)

