from collections import defaultdict, deque

def dfs(start, tree):
    visited = set([start])
    path = defaultdict(list)
    stack = [start]
    while stack:
        node = stack.pop()
        for neighbor in tree[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                path[node].append(neighbor)
                stack.append(neighbor)
    return path

def frog_meeting_in_mountain_ranges(mountain_ranges, start, end):
    tree = defaultdict(list)
    max_length = float('-inf')
    for start_val, end_val in mountain_ranges:
        if start_val > start_val:
            tree[start_val].append(start_val)
        else:
            tree[end_val].append(end_val)
        for md in range(start_val, end_val):
            if md == start_val:
                tree[md].append(end_val)
            elif md == end_val:
                tree[md].append(start_val)
            else:
                tree[md].append((start_val, end_val))
        max_length = max(max_length, end_val)
    path = dfs(end_val, tree)
    visited = set()
    meetings = 0
    for node in path[end_val]:
        stack = deque([(node, 0)])
        while stack:
            (curr, time) = stack.popleft()
            if curr == node:
                meetings += time
            else:
                visited.add(curr)
                for neighbor in path[curr]:
                    if neighbor not in visited:
                        stack.append((neighbor, time + 1))
    return meetings if meetings >= end_val - start_val else -1

