def get_smallest_string(N, P, S):
    # Track the indices of 'a's and 'b's
    ab_indices = [(i, char) for i, char in enumerate(S) if char == 'a']
    ba_indices = [(i, char) for i, char in enumerate(S) if char == 'b']

    if N % 2 == 0 and len(ab_indices) == N // 2 and len(ba_indices) == N // 2:
        return''.join(['a' if i == len(S) - i - 1 else 'b' for i in range(len(S))])

    minimum_points_used = min(len(ab_indices), len(ba_indices))

    if minimum_points_used > P:
        return ''.join(['a' if i == len(S) - i - 1 else 'b' for i in range(len(S))])

    remaining_points = P - minimum_points_used
    ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]
    ba_found = [True if len(ba_indices) > 0 and ba_indices[0][1] == 'b' else False]

    while remaining_points > 0 and ab_found and ba_found:
        if ab_indices[0][1] == 'a' and ba_indices[0][1] == 'b':
            return ''.join(['a' if i == len(S) - i - 1 else 'b' for i in range(len(S))])
        if remaining_points > 1:
            if min(remaining_points, 2) >= 2:
                ab_indices.insert(0, (ab_indices[0][0], ab_indices[0][1] + 1))
                ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]
                ba_found = [True if len(ba_indices) > 0 and ba_indices[0][1] == 'b' else False]
        elif remaining_points > 1:
            ab_indices.insert(0, (ab_indices[0][0], ab_indices[0][1] + 1))
            ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]
        else:
            if len(ab_indices) > 0 and ab_indices[0][1] == 'a':
                remains = ab_indices[0][1] - 'a'
                ab_indices.insert(0, (ab_indices[0][0], 'b' * remains))
                ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]
                ba_found = [True if len(ba_indices) > 0 and ba_indices[0][1] == 'b' else False]
                ba_indices.pop(0)
            elif len(ba_indices) > 0 and ba_indices[0][1] == 'b':
                remains = ba_indices[0][1] - 'b'
                ba_indices.insert(0, (ba_indices[0][0], 'a' * remains))
                ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]
                ba_found = [True if len(ba_indices) > 0 and ba_indices[0][1] == 'b' else False]
                ab_indices.pop(0)

        remaining_points -= 2 if ab_found else 1

        if remaining_points < 0:
            return ''.join(['a' if i == len(S) - i - 1 else 'b' for i in range(len(S))])

    # Extra operations to cover minimum remaining points
    if remaining_points > 0 and ab_indices[0][1] == 'a':
        remain = ab_indices[0][1] - 'a'
        if remaining_points:
            ab_indices.insert(0, (ab_indices[0][0], 'b' * remain))
            ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]

    if remaining_points > 0 and ba_indices[0][1] == 'b':
        remain = ba_indices[0][1] - 'b'
        if remaining_points:
            ba_indices.insert(0, (ba_indices[0][0], 'a' * remain))
            ab_found = [True if len(ab_indices) > 0 and ab_indices[0][1] == 'a' else False]

    ab_indices.sort()
    ba_indices.sort()

    result = ''.join(['b' if char in ab_indices else 'a' for char in S])
    return result


