from collections import defaultdict
from heapq import heappop, heappush

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))
    return distances

def meet_time(graph, start, end):
    distances = defaultdict(lambda: defaultdict(lambda: float('infinity')))
    distances[start][end] = 0

    for node in graph[start]:
        distances[start][node] = 1

    for _ in range(len(graph) - 1):
        for current_node in graph[start]:
            for neighbor, weight in graph[current_node].items():
                if distances[neighbor][current_node] == float('infinity'):
                    continue
                distances[neighbor][current_node] = min(distances[neighbor][current_node], weight)

    for distance in distances[end]:
        if distance != float('infinity'):
            return distance
    return float('infinity')

