def apply_magic(glue, beads):
    result = []
    while glue:
        best_chain = []
        chain_length = 1
        for i in range(len(beads) - 2):
            if i % len(beads) == 0:
                glue = beads[i] ^ beads[i + 2]
                if glue in beads[i :: 2]:
                    index = beads[i :: 2].index(glue) + i
                    if beads[i :: 2][index] not in best_chain:
                        best_chain.append(beads[i :: 2][index])
                    if beads[i :: 2][index] not in result:
                        result.append(beads[i :: 2][index])
                    if beads[i :: 2][index] != glue:
                        glue ^= beads[i :: 2][index]
                    chain_length += 1
                else:
                    glue = beads[i :: 2][0] ^ beads[i :: 2][1]
                    if beads[i :: 2][0] not in best_chain:
                        best_chain.append(beads[i :: 2][0])
                    if beads[i :: 2][0] not in result:
                        result.append(beads[i :: 2][0])
                    if beads[i :: 2][0] != glue:
                        glue ^= beads[i :: 2][0]
                    chain_length += 1
        answer = []
        for bead in best_chain:
            while chain_length >= 2 and (bead ^ best_chain[-2]) in beads:
                answer.append(result.pop())
                chain_length -= 1
            answer.append(bead)
        if glue and chain_length:
            answer.append(glue)
    return [index // 2 for index in sorted(result)]

