from math import factorial
from typing import List

MOD = 10**9 + 7

def computeWays(w: List[int]) -> int:
    n = len(w)
    w = [-wi for wi in w]
    m = max(w)
    w.sort()

    if n <= m:
        return 0

    stumps = [0]
    for i, wi in enumerate(w):
        if wi == 0:
            stumps.append(stumps[-1])
        else:
            stumps.append(stumps[-1] - wi)

    prefix = [0]
    for i in stumps:
        prefix.append(prefix[-1] + i)

    ways = 0

    for i in range(m, len(w) + 1):
        ways += fact(i)

    return pow(2, n - m, MOD) * ways * inverse(fact(len(w))), 0

def separate(n: int, a: int):
    less = 0
    if n >= a:
        less = n // a
        n -= less * a
    for i in range(a, 1, -1):
        cnt = n // i
        if cnt <= less:
            less = cnt
        n -= less * i
    return less, n

def fact(n: int) -> int:
    if n < 1000000000:
        return factorial(n)
    result, e = 1, 5
    while result < n < result ** e:
        result *= n
        e *= 2
    result *= inv(2, MOD - 2)
    return result % MOD

def inv(n, mod=2):
    return pow(n, mod - 2, mod)

