def count_paintings(w):
    N = len(w)
    @lru_cache(maxsize=None)
    def dp(i, used):
        if i == N:
            return 1
        way = 0
        for j in range(N):
            if w[j] and j != i:
                if used:
                    ways = dp(j, 0)
                elif used == (w[j] == 1):
                    ways = dp(j, 1)
                elif used == (w[j] == 2):
                    ways = dp(j, 2)
                else:
                    ways = dp(j, 3)
                way += ways * (w[j] - used) * (2 + (w[j] - used)) // 2
        return way % MOD

    return dp(0, 0)

