from collections import defaultdict, deque
from typing import List

def bfs_to_x(graph, start):
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    queue = deque([(start, 0)])

    while queue:
        curr_node, level = queue.popleft()

        for neighbor in graph[curr_node]:
            if dist[neighbor] > level + 1:
                dist[neighbor] = level + 1
                queue.append((neighbor, level + 1))

    return dist

def find_time_to_meet(graph, u, v, x, y):
    dist_u_to_x = bfs_to_x(graph, u)
    dist_v_to_x = bfs_to_x(graph, v)

    time_to_u = dist_u_to_x[x]
    time_to_v = dist_v_to_x[y]

    if time_to_u == float('inf') or time_to_v == float('inf'):
        return -1

    if time_to_u == time_to_v:
        return 0

    if time_to_u > time_to_v:
        u_to_v_duration = time_to_u - time_to_v
        time_to_x_from_v = dist_v_to_x[x] + u_to_v_duration
        time_to_x_from_u = dist_u_to_x[x]
        return max(u_to_v_duration, time_to_x_from_v - time_to_x_from_u)

    if time_to_v > time_to_u:
        v_to_u_duration = time_to_v - time_to_u
        time_to_x_from_u = dist_u_to_x[x] + v_to_u_duration
        time_to_x_from_v = dist_v_to_x[y]
        return max(v_to_u_duration, time_to_x_from_v - time_to_x_from_u)

    return -1
