def get_edge_set(input_set, query_set):
    total_size_query = len(input_set)
    query_set_size = len(query_set)
    expected_total_size_query = min(total_size_query, query_set_size)

    intersection = input_set & query_set
    non_intersection = input_set - query_set
    contained_elements = non_intersection | set(query_set)

    odd_elements = [x for x in contained_elements if x % 2 != 0]
    even_elements = [x for x in contained_elements if x % 2 == 0]

    odd_size_query = len(odd_elements)
    even_size_query = len(even_elements)

    intersect_size_query = len(intersection | odd_size_query) ^ len(intersection)
    if intersect_size_query == expected_total_size_query - 1:
        if even_size_query == expected_total_size_query - 1:
            return odd_size_query, 1
        return even_size_query - query_set_size, 0
    inters = set()
    for a in odd_elements:
        for b in even_elements:
            inters.add((a, b))

    returned_intersection = len(intersection | inters) ^ expected_total_size_query

    if returned_intersection == (total_size_query + query_set_size - 2):
        if even_size_query < query_set_size:
