from collections import defaultdict

def bfs(graph, start, target):
    queue = [(start, 0)]
    visited = set()
    while queue:
        node, dist = queue.pop(0)
        if node == target:
            return dist
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, dist + 1))
    return -1

def longest_common_path(graph, path1, path2):
    for i in range(min(len(path1), len(path2))):
        if path1[i] != path2[i]:
            return path1[i - 1], path1[i + 1], path2[i - 1], path2[i + 1]
    return (path1[i - 1], path1[i + 1], "") if i >= 1 else "", (path2[i - 1], path2[i + 1])

def solve(graph, t):
