class NecklaceMangler:
    def __init__(self):
        self.valid_pears = {}

    def find(self, color, connected_colors=None):
        if color in self.valid_pears:
            return self.valid_pears[color]
        else:
            best = 0
            for other in self.valid_pears.values():
                for val in other:
                    if color ^ val in self.valid_pears:
                        best = max(best, self.valid_pears[color ^ val] + 1)
            self.valid_pears[color] = best
            return best

    def build_chain(self, chain):
        if len(chain) == 0:
            return 0
        if len(chain) == 1:
            return self.find(chain[0])
        return max(self.find(chain[0]), self.find(chain[-1], chain[-1]) + 1)

def puzzle(N, beads):
    if N <= 1:
        return max(20, N)

    mangler = NecklaceMangler()
    max_beauty = 0
    for bead in beads:
        colored = bead.split()
        charisma = int(colored[0])
        energy = int(colored[1])

        feasibility = [
            str(an) for an in range(1, 2 * N + 1)
        ]
        min_beauty = 20
        for c in feasibility:
            beauty = mangler.find(charisma, [energy, c])
            if beauty < 20 and beauty != max_beauty:
                with_mut = mangler.find(energy, [charisma, c])
                if with_mut < beauty and with_mut != max_beauty:
                    feasibility.remove(c)
                max_beauty = beauty
            elif beauty != max_beauty and feasibility:
                min_beauty = min(min_beauty, mangler.find(charisma, feasibility))
    return str(max_beauty + 1) + '\n'
