        elif 'b' in perm and 'a' not in perm:
            perm = perm.replace('b', 'a')
        if len(perm) > 0 and perm[0] == 'a' and len(perm) < lower_case_count and alphabet_counts['b'] > 0:
            perm = perm[1:] + perm[:1]
        elif len(perm) > 0 and perm[0] == 'b' and len(perm) < lower_case_count and alphabet_counts['a'] > 0:
            perm = perm[-1] + perm[:-1]
        if is_valid_alpha(perm):
            yield perm
            break

def find_lexi_smallest_string(n, p, s):
