def count_distinct_strings(n, s):
    # Initialize the cache with dimensions N+1 x N+1
    cache = [[0] * n for _ in range(n)]

    # Fill in the cache with one operation at column 0
    for i in range(n):
        cache[n-1][i] = 'ACB' in s[i:] + cache[n-2][i]

    # Fill in the cache with more operations
    for j in range(1, n):
        for i in range(n-1):
            # Check all possible operations
            for lookup in {'ABC'.find(c) for c in 'ABC' if c != s[i:j+1][lookup] + s[j+1:]}:
                cache[i][j] += cache[lookup + 1][j] + bool(cache[i + lookup + 1][j])

    return cache[0][n-1] % (10**9 + 7)

# Example usage
n = int(input().strip())
s = input().strip()
print(count_distinct_strings(n, s))
